//!
//! Replaces: lib/base64.c

/// The RFC 4648 section 4 alphabet.
const TABLE: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

// The C types these contracts name. A Rust object has
// no C type graph to resolve them against, so they are
// not duplicates of anything -- omit one and the build
// stops naming the reference it could not resolve.
// Generated by rig/kabi-migrate.py; do not hand-edit.
kernel::kabi_rule!("type_string", "t#__u8",
    "typedef_type __u8 { base_type unsigned char byte_size(1) encoding(8) }");
kernel::kabi_rule!("type_string", "t#u8",
    "typedef_type u8 { t#__u8 }");

kernel::kabi_export! {
    base64_encode,
    license = "GPL",
    namespace = "",
    contract = "subprogram ( formal_parameter pointer_type { const_type { t#u8 } } src , formal_parameter base_type int byte_size(4) encoding(5) srclen , formal_parameter pointer_type { base_type char byte_size(1) encoding(8) } dst ) -> base_type int byte_size(4) encoding(5)",
}

/// Body of `base64_encode()`. Returns the number of bytes written to `dst`.
///
/// # Safety
/// `src` must be readable for `srclen` bytes and `dst` writable for the full
/// encoded length, which is `4 * DIV_ROUND_UP(srclen, 3)`. Same contract as
/// the C, whose callers size `dst` from `BASE64_CHARS()`.
///
/// See `include/linux/base64.h` for the C declaration.
#[no_mangle]
pub unsafe extern "C" fn base64_encode(
    src: *const u8,
    srclen: core::ffi::c_int,
    dst: *mut u8,
) -> core::ffi::c_int {
    let n = if srclen > 0 { srclen as usize } else { 0 };
    // SAFETY: the caller guarantees `srclen` readable bytes at `src`.
    // `(NULL, 0)` is legal C and `from_raw_parts` forbids a null pointer.
    let src: &[u8] = if n == 0 {
        &[]
    } else {
        unsafe { core::slice::from_raw_parts(src, n) }
    };

    let mut ac: u32 = 0;
    let mut bits: i32 = 0;
    let mut written: usize = 0;

    // SAFETY (for every put below): the caller guarantees `dst` has room for
    // the whole encoded string. `written` only ever counts bytes this
    // function has produced, and the total is the documented output length.
    let mut put = |b: u8| {
        unsafe { *dst.add(written) = b };
        written = written.wrapping_add(1);
    };

    for &byte in src {
        ac = (ac.wrapping_shl(8)) | byte as u32;
        bits = bits.wrapping_add(8);
        loop {
            bits = bits.wrapping_sub(6);
            put(TABLE[((ac.wrapping_shr(bits as u32)) & 0x3f) as usize]);
            if bits < 6 {
                break;
            }
        }
    }
    if bits != 0 {
        put(TABLE[((ac.wrapping_shl((6i32.wrapping_sub(bits)) as u32)) & 0x3f) as usize]);
        bits = bits.wrapping_sub(6);
    }
    while bits < 0 {
        put(b'=');
        bits = bits.wrapping_add(2);
    }

    written as core::ffi::c_int
}

/// Position of `c` in the base64 alphabet, or `None`.
///
/// The C uses `strchr(base64_table, src[i])`, which also matches the
/// terminating NUL -- hence its separate `src[i] == 0` test. Searching a
/// 64-byte table with no NUL in it removes the special case rather than
/// reproducing it, and the result is identical: NUL is not in the alphabet.
#[inline]
fn index_of(c: u8) -> Option<u8> {
    let mut i = 0;
    while i < TABLE.len() {
        if TABLE[i] == c {
            return Some(i as u8);
        }
        i = i.wrapping_add(1);
    }
    None
}

kernel::kabi_export! {
    base64_decode,
    license = "GPL",
    namespace = "",
    contract = "subprogram ( formal_parameter pointer_type { const_type { base_type char byte_size(1) encoding(8) } } src , formal_parameter base_type int byte_size(4) encoding(5) srclen , formal_parameter pointer_type { t#u8 } dst ) -> base_type int byte_size(4) encoding(5)",
}

/// Body of `base64_decode()`. Returns the number of bytes written to `dst`,
/// or -1 if `src` is not valid base64.
///
/// # Safety
/// `src` must be readable for `srclen` bytes and `dst` writable for the
/// decoded length, at most `3 * srclen / 4`. Same contract as the C.
///
/// See `include/linux/base64.h` for the C declaration.
#[no_mangle]
pub unsafe extern "C" fn base64_decode(
    src: *const u8,
    srclen: core::ffi::c_int,
    dst: *mut u8,
) -> core::ffi::c_int {
    let n = if srclen > 0 { srclen as usize } else { 0 };
    // SAFETY: the caller guarantees `srclen` readable bytes at `src`.
    // `(NULL, 0)` is legal C and `from_raw_parts` forbids a null pointer.
    let src: &[u8] = if n == 0 {
        &[]
    } else {
        unsafe { core::slice::from_raw_parts(src, n) }
    };

    let mut ac: u32 = 0;
    let mut bits: i32 = 0;
    let mut written: usize = 0;

    for &c in src {
        if c == b'=' {
            ac = ac.wrapping_shl(6);
            bits = bits.wrapping_add(6);
            if bits >= 8 {
                bits = bits.wrapping_sub(8);
            }
            continue;
        }
        let Some(v) = index_of(c) else {
            return -1;
        };
        ac = (ac.wrapping_shl(6)) | v as u32;
        bits = bits.wrapping_add(6);
        if bits >= 8 {
            bits = bits.wrapping_sub(8);
            // SAFETY: the caller guarantees `dst` has room for the decoded
            // output; `written` counts only bytes produced here, and a
            // 4-character group yields at most 3 of them.
            unsafe { *dst.add(written) = (ac.wrapping_shr(bits as u32)) as u8 };
            written = written.wrapping_add(1);
        }
    }

    // Trailing bits that were not consumed must be zero, or the input was
    // not produced by a conforming encoder.
    if ac & ((1u32.wrapping_shl(bits as u32)).wrapping_sub(1)) != 0 {
        return -1;
    }

    written as core::ffi::c_int
}
